// ── TechCrunch RSS parser ─────────────────────────────────────
function parseTCItems(xml) {
  const items = [];
  let pos = 0;
  while (items.length < 12) {
    const s = xml.indexOf('<item>', pos);
    if (s < 0) break;
    const e = xml.indexOf('</item>', s);
    if (e < 0) break;
    const b = xml.slice(s + 6, e);
    pos = e + 7;
    function gv(tag) {
      const open = '<' + tag + '>', close = '</' + tag + '>';
      const si = b.indexOf(open), ei = b.indexOf(close);
      if (si < 0 || ei < 0) return '';
      return b.slice(si + open.length, ei).replace(/<![CDATA[/g,'').replace(/]]>/g,'').replace(/<[^>]+>/g,'').trim();
    }
    const title = gv('title');
    if (!title || title.length < 4) continue;
    const ls = b.indexOf('<link>'), le = b.indexOf('</link>');
    const link = (ls >= 0 && le >= 0) ? b.slice(ls + 6, le).trim() : '';
    items.push({ source: 'TechCrunch', category: 'Trending', title, url: link, description: gv('description').slice(0,300), published: gv('pubDate') });
  }
  return items;
}

function msToTime(ms) {
  const s = Math.floor((ms || 0) / 1000);
  return Math.floor(s / 60) + ':' + String(s % 60).padStart(2,'0');
}

// ── rss2json parser (JSON response) ──────────────────────────
function parseR2JItems(items, chName, chCat, cutoff) {
  const videos = [];
  if (!Array.isArray(items)) return videos;
  for (var i = 0; i < items.length; i++) {
    try {
      const item = items[i];
      const pub = item.pubDate ? item.pubDate.replace(' ', 'T') : '';
      if (pub && new Date(pub) < cutoff) continue;
      const url = item.link || '';
      if (!url.includes('youtube.com')) continue;
      const vi = url.indexOf('v=');
      const videoId = (vi >= 0) ? url.slice(vi + 2, vi + 13) : null;
      if (!videoId || videoId.length !== 11) continue;
      const title = (item.title || '').trim();
      if (!title) continue;
      const desc = (item.description || '').replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').slice(0,400);
      const thumb = item.thumbnail || item.enclosure && item.enclosure.link || ('https://i.ytimg.com/vi/' + videoId + '/hqdefault.jpg');
      videos.push({ videoId, title, url, published: item.pubDate || '', description: desc, thumbnail: thumb, views: 0, channel: chName, category: chCat });
    } catch(ex) { continue; }
  }
  return videos;
}

// ── Atom XML parser (fallback) ────────────────────────────────
function parseAtomFeed(xml, chName, chCat, cutoff) {
  const videos = [];
  if (!xml || xml.indexOf('<entry>') < 0) return videos;
  let pos = 0;
  while (true) {
    const s = xml.indexOf('<entry>', pos);
    if (s < 0) break;
    const e = xml.indexOf('</entry>', s);
    if (e < 0) break;
    pos = e + 8;
    try {
      const b = xml.slice(s + 7, e);
      const ps = b.indexOf('<published>'), pe = b.indexOf('</published>');
      const pub = (ps >= 0 && pe >= 0) ? b.slice(ps + 11, pe).trim() : '';
      if (pub && new Date(pub) < cutoff) continue;
      const ts = b.indexOf('<title>'), te = b.indexOf('</title>');
      const title = (ts >= 0 && te >= 0) ? b.slice(ts + 7, te).trim() : '';
      if (!title) continue;
      const li = b.indexOf('href="');
      const url = (li >= 0) ? b.slice(li + 6, b.indexOf('"', li + 6)) : '';
      if (!url.includes('youtube.com/watch')) continue;
      const vi = url.indexOf('v=');
      const videoId = (vi >= 0) ? url.slice(vi + 2, vi + 13) : null;
      if (!videoId || videoId.length !== 11) continue;
      const ds = b.indexOf('<media:description>'), de = b.indexOf('</media:description>');
      const desc = (ds >= 0 && de >= 0) ? b.slice(ds + 19, de).replace(/<[^>]+>/g,'').slice(0,400) : '';
      const thumbIdx = b.indexOf('<media:thumbnail');
      const tuIdx = thumbIdx >= 0 ? b.indexOf('url="', thumbIdx) : -1;
      const thumb = (tuIdx >= 0) ? b.slice(tuIdx + 5, b.indexOf('"', tuIdx + 5)) : ('https://i.ytimg.com/vi/' + videoId + '/hqdefault.jpg');
      videos.push({ videoId, title, url, published: pub, description: desc, thumbnail: thumb, views: 0, channel: chName, category: chCat });
    } catch(ex) { continue; }
  }
  return videos;
}

// ── RSS fetch: rss2json PRIMARY + direct fallback ─────────────
async function fetchRSS(ch) {
  const ytRssUrl = 'https://www.youtube.com/feeds/videos.xml?channel_id=' + ch.id;
  const hasKey = cfg.RSS2JSON_KEY && cfg.RSS2JSON_KEY !== 'PASTE_YOUR_FREE_RSS2JSON_KEY_HERE';
  const keyParam = hasKey ? '&api_key=' + cfg.RSS2JSON_KEY : '';
  const countParam = hasKey ? '&count=15' : '';
  const r2jUrl = 'https://api.rss2json.com/v1/api.json?rss_url=' + encodeURIComponent(ytRssUrl) + countParam + keyParam;

  // Method 1: rss2json — works from any server IP
  try {
    const raw = await $helpers.httpRequest({ method: 'GET', url: r2jUrl, timeout: 15000 });
    // n8n may return a parsed object OR a string — handle both
    let d = raw;
    if (typeof raw === 'string') { try { d = JSON.parse(raw); } catch(e2) { d = {}; } }
    else if (raw && typeof raw === 'object' && raw.body) { try { d = JSON.parse(raw.body); } catch(e2) { d = raw; } }
    else if (raw && typeof raw === 'object' && raw.json) { d = raw.json; }
    const items = d && d.items ? d.items : (d && d.data && d.data.items ? d.data.items : null);
    const statusOk = d && (d.status === 'ok' || (items && items.length > 0));
    console.log('[rss2json] ' + ch.name + ' raw_type=' + typeof raw + ' d_status=' + (d && d.status) + ' items=' + (items ? items.length : 'null') + (d && d.message ? ' msg=' + d.message : ''));
    if (statusOk && Array.isArray(items) && items.length > 0) {
      console.log('[rss2json OK] ' + ch.name + ': ' + items.length + ' items');
      return { ch, items: items, xml: null, method: 'rss2json' };
    }
  } catch(e) { console.log('[rss2json FAIL] ' + ch.name + ': ' + e.message); }

  // Method 2: Direct YouTube RSS (may work if n8n cloud IP not blocked)
  try {
    const r = await $helpers.httpRequest({
      method: 'GET',
      url: ytRssUrl,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36' },
      timeout: 12000
    });
    const xml = (typeof r === 'string') ? r : (r.data || r.body || '');
    if (xml && xml.includes('<entry>')) {
      console.log('[Direct RSS OK] ' + ch.name);
      return { ch, items: null, xml: xml, method: 'direct' };
    }
    console.log('[Direct RSS WARN] ' + ch.name + ': no <entry> in response (length=' + (xml||'').length + ')');
  } catch(e) { console.log('[Direct RSS FAIL] ' + ch.name + ': ' + e.message); }

  // Method 3: allorigins CORS proxy
  try {
    const proxyUrl = 'https://api.allorigins.win/raw?url=' + encodeURIComponent(ytRssUrl);
    const r = await $helpers.httpRequest({ method: 'GET', url: proxyUrl, timeout: 15000 });
    const xml = (typeof r === 'string') ? r : (r.data || r.body || '');
    if (xml && xml.includes('<entry>')) {
      console.log('[Proxy RSS OK] ' + ch.name);
      return { ch, items: null, xml: xml, method: 'proxy' };
    }
  } catch(e) { console.log('[Proxy RSS FAIL] ' + ch.name + ': ' + e.message); }

  console.log('[ALL RSS FAIL] ' + ch.name);
  return { ch, items: [], xml: '', method: 'failed' };
}

// ── Transcript: Firecrawl primary + caption URL + description fallback ───────
async function getTranscript(vid) {

  // Method 1: Firecrawl — scrapes YouTube page, returns description + top comments + metadata
  try {
    const r = await $helpers.httpRequest({
      method: 'POST',
      url: 'https://api.firecrawl.dev/v1/scrape',
      headers: { 'Authorization': 'Bearer ' + cfg.FIRECRAWL_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({ url: vid.url, formats: ['markdown'] }),
      timeout: 25000
    });
    const d = (typeof r === 'string') ? JSON.parse(r) : r;
    const md = (d && d.data && d.data.markdown) ? d.data.markdown : '';
    if (md && md.length > 300) {
      console.log('[Firecrawl OK] ' + vid.videoId + ' — ' + md.length + ' chars');
      return { t: md.slice(0, 7000), src: 'Firecrawl (page content + comments)' };
    }
    console.log('[Firecrawl WARN] ' + vid.videoId + ' — short response: ' + md.length + ' chars');
  } catch(e) { console.log('[Firecrawl FAIL] ' + vid.videoId + ': ' + e.message); }

  // Method 2: Extract signed caption URL from YouTube page HTML, then fetch transcript
  try {
    const page = await $helpers.httpRequest({
      method: 'GET',
      url: 'https://www.youtube.com/watch?v=' + vid.videoId,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36', 'Accept-Language': 'en-US,en;q=0.9' },
      timeout: 12000
    });
    const pageText = (typeof page === 'string') ? page : (page.data || page.body || '');
    const capIdx = pageText.indexOf('"captionTracks":[');
    if (capIdx >= 0) {
      const chunk = pageText.slice(capIdx, capIdx + 3000);
      const bi = chunk.indexOf('"baseUrl"');
      if (bi >= 0) {
        const vs = chunk.indexOf('"', bi + 9) + 1;
        const ve = chunk.indexOf('"', vs);
        const rawUrl = chunk.slice(vs, ve);
        const captionUrl = rawUrl.replace(/\\u0026/g, '&').replace(/\\\//g, '/') + '&fmt=json3';
        if (captionUrl.startsWith('http') && captionUrl.length > 50) {
          const tx = await $helpers.httpRequest({
            method: 'GET', url: captionUrl,
            headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
            timeout: 10000
          });
          const txText = (typeof tx === 'string') ? tx : (tx.data || tx.body || '');
          if (txText && txText.length > 50) {
            const txData = (typeof txText === 'string') ? JSON.parse(txText) : txText;
            if (txData && Array.isArray(txData.events) && txData.events.length > 5) {
              const segs = txData.events
                .filter(function(ev) { return Array.isArray(ev.segs); })
                .map(function(ev) { var t = Math.floor((ev.tStartMs||0)/1000); return '[' + Math.floor(t/60) + ':' + String(t%60).padStart(2,'0') + '] ' + ev.segs.map(function(s){ return (s.utf8||'').replace(/\n/g,' '); }).join('').trim(); })
                .filter(function(l) { return l.length > 8; })
                .slice(0, 250);
              if (segs.length > 5) {
                console.log('[Caption URL OK] ' + vid.videoId + ' — ' + segs.length + ' segments');
                return { t: segs.join('\n'), src: 'YouTube Caption URL (' + segs.length + ' segs)' };
              }
            }
          }
        }
      }
    }
    console.log('[Caption URL] ' + vid.videoId + ' — no captions found in page');
  } catch(e) { console.log('[Caption URL FAIL] ' + vid.videoId + ': ' + e.message); }

  // Method 3: Description — always works
  console.log('[Desc Fallback] ' + vid.videoId);
  return { t: '[Video description — no transcript available]\n\n' + (vid.description || 'No description.'), src: 'Description Only' };
}

// ── MAIN ─────────────────────────────────────────────────────
const cutoff = new Date(cfg.cutoff);

// Parse TechCrunch trending
const trendingItems = parseTCItems(tcXml);
console.log('[Trending] ' + trendingItems.length + ' items from TechCrunch');

// Fetch all 12 YouTube channel feeds in parallel
console.log('[RSS] Fetching ' + cfg.channels.length + ' channels in parallel...');
const rssResults = await Promise.all(cfg.channels.map(function(ch) { return fetchRSS(ch); }));

// Parse videos from results
let allVideos = [];
for (var i = 0; i < rssResults.length; i++) {
  const res = rssResults[i];
  var vids = [];
  if (res.method === 'rss2json') {
    vids = parseR2JItems(res.items, res.ch.name, res.ch.cat, cutoff);
  } else if (res.xml && res.xml.includes('<entry>')) {
    vids = parseAtomFeed(res.xml, res.ch.name, res.ch.cat, cutoff);
  }
  console.log('[Parse] ' + res.ch.name + ' (' + res.method + '): ' + vids.length + ' videos in 7d');
  allVideos = allVideos.concat(vids);
}

// Deduplicate + sort by publish date (newest first)
const seen = new Set();
allVideos = allVideos
  .filter(function(v) { if (seen.has(v.videoId)) return false; seen.add(v.videoId); return true; })
  .sort(function(a, b) { return new Date(b.published) - new Date(a.published); });
console.log('[Total] ' + allVideos.length + ' unique videos found');

// Fetch transcripts for top 5 (newest)
const topN = Math.min(5, allVideos.length);
const topVids  = allVideos.slice(0, topN);
const restVids = allVideos.slice(topN).map(function(v) {
  return Object.assign({}, v, { transcript: v.description, transcriptSource: 'description only' });
});

console.log('[Transcript] Fetching for top ' + topN + ' videos in parallel...');
const txResults = await Promise.all(topVids.map(function(v) { return getTranscript(v); }));
for (var j = 0; j < topVids.length; j++) {
  topVids[j].transcript       = txResults[j].t;
  topVids[j].transcriptSource = txResults[j].src;
  console.log('[Transcript] "' + topVids[j].title.slice(0,45) + '" → ' + txResults[j].src);
}

const finalVideos = topVids.concat(restVids);
console.log('[DONE] ' + topN + ' with transcript + ' + restVids.length + ' without. Total: ' + finalVideos.length);

return [{ json: Object.assign({}, cfg, {
  allVideos: finalVideos,
  trendingItems: trendingItems,
  totalVideos: allVideos.length,
  transcriptCount: topN
}) }];

const d = $input.item.json;
const allVideos    = d.allVideos    || [];
const trendingItems = d.trendingItems || [];

const transcriptBlock = allVideos.slice(0,5).map(function(v, i) {
  return '=== VIDEO ' + (i+1) + ': ' + v.title + ' ===\n'
    + 'Channel: ' + v.channel + ' | Category: ' + v.category + '\n'
    + 'URL: ' + v.url + '\n'
    + 'Views: ' + (v.views || 0).toLocaleString() + ' | Published: ' + (v.published || '') + '\n'
    + 'Transcript Source: ' + (v.transcriptSource || 'unknown') + '\n\n'
    + 'TRANSCRIPT:\n' + (v.transcript || '(none)').slice(0, 5000);
}).join('\n\n---\n\n');

const videoListBlock = allVideos.map(function(v, i) {
  return (i+1) + '. [' + v.category + '] ' + v.channel + ': "' + v.title + '" | ' + (v.views||0).toLocaleString() + ' views | ' + v.url;
}).join('\n');

const trendingBlock = trendingItems.map(function(t) {
  return '• ' + t.title + ' — ' + (t.description || '').slice(0,120) + (t.url ? ' | ' + t.url : '');
}).join('\n');

const prompt = 'You are a sharp AI + Tech + Business curator. Today is ' + d.today + '.\n\n'
  + '== TRENDING TECH NEWS (TechCrunch) ==\n' + (trendingBlock || 'No trending data.') + '\n\n'
  + '== ALL YOUTUBE VIDEOS THIS WEEK (' + allVideos.length + ' total) ==\n' + (videoListBlock || 'No videos.') + '\n\n'
  + '== TOP ' + Math.min(5, allVideos.length) + ' VIDEOS — FULL TRANSCRIPTS ==\n' + (transcriptBlock || 'No transcripts.') + '\n\n'
  + '== YOUR TASK ==\n'
  + 'Write a high-value daily digest. Use EXACTLY these section headers (ALL CAPS):\n\n'
  + 'HEADLINE OF THE DAY\n'
  + 'One bold sentence — the most important development right now.\n\n'
  + 'TOP VIDEOS THIS WEEK\n'
  + 'For each of the top 5: title | channel | 2-sentence summary of what was covered | direct link\n\n'
  + 'KEY INSIGHTS FROM TRANSCRIPTS\n'
  + '5 specific bullet points drawn directly from the video transcripts — real quotes, data points, or unique insights mentioned by creators. Be specific, not generic.\n\n'
  + 'AI & AUTOMATION HIGHLIGHTS\n'
  + '3 bullet points on the most important AI/automation developments.\n\n'
  + 'BUSINESS & STARTUP SIGNALS\n'
  + '2 bullet points — key business/startup/SaaS signals from this week.\n\n'
  + 'TRENDING IN TECH (from TechCrunch)\n'
  + '3 key stories with a one-line commentary on why each matters.\n\n'
  + 'WHAT TO BUILD THIS WEEK\n'
  + '1 specific, concrete product or automation idea inspired by this week content.\n\n'
  + 'QUOTE OF THE DAY\n'
  + 'One memorable, specific quote from one of the transcripts (cite channel).\n\n'
  + 'Tone: direct, intelligent, zero fluff. Plain text only — NO markdown asterisks or hashes.';

const claudeRequest = JSON.stringify({
  model: d.CLAUDE_MODEL || 'claude-sonnet-4-6',
  max_tokens: 4000,
  messages: [{ role: 'user', content: prompt }]
});

console.log('[Prompt] ' + prompt.length + ' chars | videos: ' + allVideos.length + ' | transcripts: ' + d.transcriptCount);
return [{ json: Object.assign({}, d, { claudeRequest: claudeRequest }) }];

const prev       = $('Code: Build Claude Request').item.json;
const claudeResp = $input.item.json;

// Extract Claude text
let digestText = 'Digest unavailable — Claude API did not respond correctly.';
try {
  const text = claudeResp && claudeResp.content && claudeResp.content[0] && claudeResp.content[0].text;
  if (text && text.length > 50) digestText = text;
} catch(e) { console.log('[Claude parse error] ' + e.message); }

const allVideos     = prev.allVideos     || [];
const trendingItems = prev.trendingItems || [];

// Video card HTML
function fmtNum(n) {
  const x = parseInt(n) || 0;
  if (x >= 1000000) return (x/1000000).toFixed(1) + 'M';
  if (x >= 1000)    return (x/1000).toFixed(0)    + 'K';
  return x.toString();
}

function timeAgo(isoStr) {
  if (!isoStr) return '';
  const diff = Date.now() - new Date(isoStr).getTime();
  const days = Math.floor(diff / 86400000);
  return days === 0 ? 'Today' : days + 'd ago';
}

const videoCardsHtml = allVideos.slice(0,5).map(function(v, i) {
  const hasRealTranscript = v.transcriptSource && v.transcriptSource !== 'Description Fallback' && v.transcriptSource !== 'description only';
  const badge = hasRealTranscript
    ? '<span style="background:#065f46;color:#a7f3d0;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;">TRANSCRIPT</span>'
    : '<span style="background:#374151;color:#9ca3af;padding:2px 8px;border-radius:10px;font-size:10px;">DESC ONLY</span>';
  return '<div style="border:1px solid #1f2937;border-radius:12px;overflow:hidden;margin-bottom:16px;background:#111827;">'
    + '<table cellpadding="0" cellspacing="0" width="100%"><tr>'
    + '<td width="160" valign="top" style="padding:0;">'
    + '<a href="' + v.url + '" target="_blank"><img src="' + (v.thumbnail || '') + '" width="160" height="90" alt="" style="display:block;object-fit:cover;"/></a>'
    + '</td>'
    + '<td valign="top" style="padding:12px 14px;">'
    + '<p style="margin:0 0 4px;font-size:10px;color:#6b7280;">#' + (i+1) + ' &nbsp;' + badge + ' &nbsp;<span style="color:#6b7280;">' + timeAgo(v.published) + '</span></p>'
    + '<a href="' + v.url + '" target="_blank" style="text-decoration:none;"><p style="margin:0 0 4px;color:#f9fafb;font-size:14px;font-weight:700;line-height:1.4;">' + (v.title || '') + '</p></a>'
