// Parse digest sections
const SECTIONS = ['HEADLINE OF THE DAY','TOP VIDEOS THIS WEEK','KEY INSIGHTS FROM TRANSCRIPTS','AI & AUTOMATION HIGHLIGHTS','BUSINESS & STARTUP SIGNALS','TRENDING IN TECH','WHAT TO BUILD THIS WEEK','QUOTE OF THE DAY'];
function extractSection(text, heading) {
  const idx = text.indexOf(heading);
  if (idx < 0) return '';
  const start = idx + heading.length;
  let end = text.length;
  for (var i = 0; i < SECTIONS.length; i++) {
    if (SECTIONS[i] === heading) continue;
    const ni = text.indexOf(SECTIONS[i], start);
    if (ni > 0 && ni < end) end = ni;
  }
  return text.slice(start, end).trim();
}

function sectionHtml(heading, content, accentColor) {
  if (!content) return '';
  const lines = content.split('\n').filter(function(l) { return l.trim().length > 0; });
  const bodyHtml = lines.map(function(line) {
    const linked = line.replace(/(https?:\/\/[^\s]+)/g, '<a href="$1" style="color:#818cf8;">$1</a>');
    if (/^[\u2022\-\*]|^\d+\./.test(line.trim())) {
      return '<p style="margin:4px 0 4px 8px;color:#d1d5db;font-size:13px;">' + linked + '</p>';
    }
    return '<p style="margin:4px 0;color:#e5e7eb;font-size:13px;line-height:1.65;">' + linked + '</p>';
  }).join('');
  return '<div style="margin-bottom:24px;">'
    + '<p style="margin:0 0 8px;font-size:11px;font-weight:800;color:' + accentColor + ';text-transform:uppercase;letter-spacing:1.5px;">' + heading + '</p>'
    + bodyHtml
    + '</div>';
}

